def render_page_author(payload: Mapping[str, Any], *, workspace_root: str | Path = ".") -> dict[str, Any]:
    """Render a complete candidate from schema input and validate it immediately."""

    if not isinstance(payload, Mapping):
        return _failed("render", "input-not-object", "render 输入必须是 JSON 对象。")
    contract, failure = _contract_result(
        "render",
        payload.get("page_type"),
        payload.get("mode"),
        contract_version=payload.get("contract_version", HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION),
        schema_version=payload.get("schema_version", HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION),
    )
    if failure:
        return failure
    assert contract is not None
    mode = str(payload["mode"])
    failure = _validate_top_level(payload, mode)
    if failure:
        return failure
    failure = _validate_nested_input(
        "render", contract, payload.get("evidence"), payload.get("validation_context")
    )
    if failure:
        return failure
    declared_boundary = str(payload.get("applicability_boundary") or "").strip()
    if declared_boundary and declared_boundary != contract.applicability_boundary:
        return _failed(
            "render",
            "target-drift",
            "输入适用边界与当前页面合同不一致。",
            expected=contract.applicability_boundary,
            actual=declared_boundary,
        )

    missing = _base_missing_fields(payload, contract)
    section_contracts = _section_by_id(contract)
    markdown = ""
    source: Path | None = None
    source_sha256: str | None = None
    authored_section_contexts: dict[str, dict[str, Any]] = {}

    if mode == "new":
        title = str(payload.get("title") or "").strip()
        sections_value = payload.get("sections")
        if not title:
            missing.append("title")
        if not isinstance(sections_value, Mapping):
            missing.append("sections")
            sections_value = {}
        unknown_sections = sorted(set(sections_value) - set(section_contracts))
        if unknown_sections:
            return _failed(
                "render",
                "unknown-field",
                "sections 包含当前页面类型未定义的字段。",
                fields=[f"sections.{field}" for field in unknown_sections],
            )
        normalized: dict[str, dict[str, Any]] = {}
        for section in contract.required_sections:
            value = sections_value.get(section.section_id)
            if value is None:
                missing.append(f"sections.{section.section_id}.human_summary")
                if section.heading_pattern:
                    missing.append(f"sections.{section.section_id}.heading")
                continue
            item, failure = _normalize_section_input("render", section, value)
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section.section_id}.human_summary")
            if section.heading_pattern and not item["heading"]:
                missing.append(f"sections.{section.section_id}.heading")
            normalized[section.section_id] = item
            authored_section_contexts[section.section_id] = _section_validation_context(item)
        for section in contract.optional_sections:
            if section.section_id not in sections_value:
                continue
            item, failure = _normalize_section_input("render", section, sections_value[section.section_id])
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section.section_id}.human_summary")
            normalized[section.section_id] = item
            authored_section_contexts[section.section_id] = _section_validation_context(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        rendered_sections = [
            _render_section(section, normalized[section.section_id])
            for section in contract.required_sections + contract.optional_sections
            if section.section_id in normalized
        ]
        markdown = f"# {title}\n\n" + "\n\n".join(rendered_sections) + "\n"
    elif mode == "supplement":
        if "title" in payload:
            return _failed(
                "render",
                "duplicate-title",
                "补充模式复用来源页标题，不接收或复制一级标题。",
                field="title",
            )
        source, existing, failure = _load_source_for_render(payload, workspace_root)
        if failure:
            return failure
        assert source is not None and existing is not None
        source_sha256 = _sha256_text(existing)
        sections_value = payload.get("sections")
        if not isinstance(sections_value, Mapping) or not sections_value:
            missing.append("sections")
            sections_value = {}
        unknown_sections = sorted(set(sections_value) - set(section_contracts))
        if unknown_sections:
            return _failed(
                "render",
                "unknown-field",
                "sections 包含当前页面类型未定义的字段。",
                fields=[f"sections.{field}" for field in unknown_sections],
            )
        _headings, existing_sections = _document_sections(existing)
        additions: list[str] = []
        for section_id, value in sections_value.items():
            section = section_contracts[str(section_id)]
            if any(_matches(section, item) for item in existing_sections):
                return _failed(
                    "render",
                    "field-already-satisfied",
                    "补充模式只接收当前页面缺少的章节。",
                    field=f"sections.{section_id}",
                )
            item, failure = _normalize_section_input("render", section, value)
            if failure:
                return failure
            assert item is not None
            if not item["human_summary"]:
                missing.append(f"sections.{section_id}.human_summary")
            additions.append(_render_section(section, item))
            authored_section_contexts[str(section_id)] = _section_validation_context(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        markdown = existing.rstrip() + "\n\n" + "\n\n".join(additions) + "\n"
    else:
        source, existing, failure = _load_source_for_render(payload, workspace_root)
        if failure:
            return failure
        assert source is not None and existing is not None
        source_sha256 = _sha256_text(existing)
        revisions = payload.get("revisions")
        if not isinstance(revisions, list) or not revisions:
            missing.append("revisions")
            revisions = []
        normalized_revisions: list[dict[str, Any]] = []
        for index, revision in enumerate(revisions):
            if not isinstance(revision, Mapping):
                return _failed(
                    "render",
                    "field-type-invalid",
                    "revisions 条目必须是对象。",
                    field=f"revisions[{index}]",
                )
            allowed_revision = {
                "section_id",
                "current",
                "human_summary",
                "key_entities",
                "links",
                "metrics",
                "source_refs",
                "machine_evidence_refs",
            }
            unknown = sorted(set(revision) - allowed_revision)
            if unknown:
                return _failed(
                    "render",
                    "unknown-field",
                    "revisions 条目包含未知字段。",
                    fields=[f"revisions[{index}].{field}" for field in unknown],
                )
            item: dict[str, Any] = {
                name: str(revision.get(name) or "").strip()
                for name in ("section_id", "current", "human_summary")
            }
            for name in ("section_id", "current", "human_summary"):
                if not item[name]:
                    missing.append(f"revisions[{index}].{name}")
            for name in ("key_entities", "links", "metrics", "source_refs", "machine_evidence_refs"):
                value = revision.get(name, [])
                if not isinstance(value, list):
                    return _failed(
                        "render",
                        "field-type-invalid",
                        "revision 的实体、链接、来源和证据引用必须是数组。",
                        field=f"revisions[{index}].{name}",
                    )
                item[name] = list(value)
            if not item["source_refs"]:
                missing.append(f"revisions[{index}].source_refs")
            if item["section_id"] and item["section_id"] not in section_contracts:
                return _failed(
                    "render",
                    "unknown-field",
                    "revision 指向当前页面类型未定义的章节。",
                    field=f"revisions[{index}].section_id",
                )
            normalized_revisions.append(item)
        if missing:
            return _missing("render", contract.page_type, mode, missing)
        markdown = existing
        _headings, existing_sections = _document_sections(existing)
        for index, revision in enumerate(normalized_revisions):
            section = section_contracts[revision["section_id"]]
            matches = [item for item in existing_sections if _matches(section, item)]
            if len(matches) != 1 or revision["current"] not in str(matches[0]["body"]):
                return _failed(
                    "render",
                    "revision-target-missing",
                    "修订目标段落未在指定章节中唯一定位。",
                    field=f"revisions[{index}].current",
                    section_id=revision["section_id"],
                )
            if markdown.count(revision["current"]) != 1:
                return _failed(
                    "render",
                    "revision-target-conflict",
                    "修订目标段落在页面中出现多次。",
                    field=f"revisions[{index}].current",
                )
            markdown = markdown.replace(revision["current"], revision["human_summary"], 1)
            authored_section_contexts[revision["section_id"]] = _section_validation_context(revision)
        if not markdown.endswith("\n"):
            markdown += "\n"

    context = payload.get("validation_context")
    assert isinstance(context, Mapping)
    merged_context = {
        "current_facts": list(context.get("current_facts", [])) if isinstance(context.get("current_facts", []), list) else context.get("current_facts"),
        "sections": dict(context.get("sections", {})) if isinstance(context.get("sections", {}), Mapping) else context.get("sections"),
    }
    if isinstance(merged_context["sections"], dict):
        merged_context["sections"].update(authored_section_contexts)
    validation = _candidate_validation(
        contract,
        markdown,
        evidence=payload.get("evidence"),
        context=merged_context,
        declared_boundary=payload.get("applicability_boundary"),
    )
    if validation["status"] != "passed":
        return {
            "errors": validation["errors"],
            "mode": mode,
            "operation": "render",
            "page_type": contract.page_type,
            "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
            "status": "failed",
            "validation": validation,
        }
    section_evidence = _section_evidence_document(contract, merged_context)
    section_evidence_bytes = (
        json.dumps(section_evidence, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n"
    ).encode("utf-8")
    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "markdown": markdown,
        "markdown_sha256": _sha256_text(markdown),
        "mode": mode,
        "operation": "render",
        "page_type": contract.page_type,
        "schema_version": HUMAN_PAGE_AUTHORING_SCHEMA_VERSION,
        "section_evidence": section_evidence,
        "section_evidence_sha256": hashlib.sha256(section_evidence_bytes).hexdigest(),
        "validation_context": merged_context,
        "source": {"path": str(source), "sha256": source_sha256} if source else None,
        "status": "ready",
        "validation": validation,
    }

def _package_route(page_type: str) -> dict[str, Any]:
    if page_type in _RECORD_TYPES:
        return {
            "entrypoint": "record",
            "command": [
                "ckb.py",
                "record",
                "--out",
                "OUTPUT",
                "--kind",
                page_type,
                "--title",
                "TITLE",
                "--body",
                "BODY.md",
                "--from-pack",
                "PACK.json",
            ],
        }
    if page_type == "reference":
        return {
            "entrypoint": "reference",
            "command": ["ckb.py", "reference", "review", "--out", "OUTPUT", "--review", "REVIEW.json"],
        }
    if page_type == "feedback":
        return {
            "entrypoint": "feedback",
            "command": [
                "ckb.py",
                "feedback",
                "create",
                "--out",
                "OUTPUT",
                "--target",
                "TARGET",
                "--start-line",
                "START",
                "--end-line",
                "END",
                "--comment",
                "BODY.md",
                "--author",
                "AUTHOR",
            ],
        }
    if page_type == "learning-note":
        return {
            "entrypoint": "learning-note-generator",
            "plugin_command": "Ask about selection and save to daily learning note",
        }
    if page_type == "README":
        return {
            "entrypoint": "README-submit",
            "submission": "提交 BODY.md 供发布包 README 人工审阅；不写生成投影。",
        }
    if page_type in _NAVIGATION_TYPES:
        return {
            "entrypoint": f"{page_type}-generator",
            "command": ["ckb.py", "human-refresh", "--out", "OUTPUT"],
        }
    if page_type == "responsibility":
        return {
            "entrypoint": "responsibility-generator",
            "command": [
                "ckb.py",
                "review-pack",
                "--out",
                "OUTPUT",
                "--pack",
                "PACK_ID",
                "--review",
                "REVIEW.json",
            ],
        }
    raise RuntimeError(f"unrouted human page type: {page_type}")

def _staging_target(
    staging_dir: str | Path, workspace_root: str | Path
) -> tuple[Path | None, dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    target = Path(staging_dir)
    if not target.is_absolute():
        target = root / target
    target = target.resolve()
    if target == root or root not in target.parents:
        return None, _failed(
            "package",
            "path-outside-workspace",
            "staging 路径必须是 workspace_root 内的新目录。",
            path=str(target),
            workspace_root=str(root),
        )
    relative = target.relative_to(root)
    forbidden = {"human", "markdown", "machine"} & {part.casefold() for part in relative.parts}
    if forbidden or target.suffix.casefold() in {".sqlite", ".db"}:
        return None, _failed(
            "package",
            "managed-target-forbidden",
            "staging 包不得写入 human、markdown、machine 或 SQLite 受管路径。",
            path=str(target),
        )
    if target.exists():
        return None, _failed(
            "package",
            "staging-target-exists",
            "staging 包目录已存在；为避免覆盖，必须使用新目录。",
            path=str(target),
        )
    return target, None

def _portable_section_evidence(
    section_evidence: Mapping[str, Any],
    workspace_root: str | Path,
) -> tuple[dict[str, Any] | None, list[tuple[Path, str, str]], dict[str, Any] | None]:
    root = Path(workspace_root).resolve()
    packaged_sections: list[dict[str, Any]] = []
    copy_plan: list[tuple[Path, str, str]] = []
    for section in section_evidence.get("sections", []):
        if not isinstance(section, Mapping):
            continue
        section_id = str(section.get("section_id") or "")
        packaged_section = {
            "disclosure_level": str(section.get("disclosure_level") or ""),
            "heading": str(section.get("heading") or ""),
            "machine_evidence_refs": [],
            "section_id": section_id,
            "source_refs": [],
        }
        for field in ("source_refs", "machine_evidence_refs"):
            values = section.get(field, [])
            if not isinstance(values, list):
                continue
            for index, item in enumerate(values):
                if not isinstance(item, Mapping):
                    continue
                target = str(item.get("target") or "").strip()
                is_windows_drive = bool(re.match(r"^[A-Za-z]:[\\/]", target))
                if _REFERENCE_URI_RE.match(target) and not is_windows_drive:
                    packaged_section[field].append({**dict(item), "target_basis": "uri"})
                    continue
                candidate = Path(target)
                if not candidate.is_absolute():
                    candidate = root / candidate
                candidate = candidate.resolve()
                if candidate != root and root not in candidate.parents:
                    return None, [], _failed(
                        "package",
                        "reference-target-outside-workspace",
                        "章节来源或机器证据路径越过 workspace_root。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                    )
                if not candidate.is_file():
                    return None, [], _failed(
                        "package",
                        "reference-target-not-found",
                        "章节来源或机器证据路径不是可读取文件。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                    )
                expected = str(item.get("sha256") or "").strip().casefold()
                if not _SHA256_RE.fullmatch(expected):
                    return None, [], _failed(
                        "package",
                        "reference-target-sha256-missing",
                        "文件型来源或机器证据引用必须提供小写 SHA-256。",
                        field=f"section_evidence.{section_id}.{field}[{index}].sha256",
                        target=target,
                    )
                actual = hashlib.sha256(candidate.read_bytes()).hexdigest()
                if actual != expected:
                    return None, [], _failed(
                        "package",
                        "reference-target-drift",
                        "章节来源或机器证据文件与声明 SHA-256 不一致。",
                        field=f"section_evidence.{section_id}.{field}[{index}]",
                        target=target,
                        expected_sha256=expected,
                        actual_sha256=actual,
                    )
                portable_target = Path("evidence") / expected / candidate.name
                portable_value = {
                    **dict(item),
                    "original_target": target,
                    "package_owned": True,
                    "target": portable_target.as_posix(),
                    "target_basis": "manifest-parent",
                }
                packaged_section[field].append(portable_value)
                copy_plan.append((candidate, portable_target.as_posix(), expected))
        for field in ("source_refs", "machine_evidence_refs"):
            packaged_section[field] = sorted(
                packaged_section[field],
                key=lambda item: (
                    str(item.get("target") or ""),
                    str(item.get("kind") or ""),
                    str(item.get("purpose") or ""),
                    str(item.get("sha256") or ""),
                ),
            )
        packaged_sections.append(packaged_section)
    portable = {
        "schema_version": 2,
        "target_resolution": {
            "file_target_basis": "manifest-parent",
            "package_owned_directory": "evidence",
            "uri_target_basis": "uri",
        },
        "sections": packaged_sections,
    }
    unique_plan = {
        (target, digest): (source, target, digest)
        for source, target, digest in copy_plan
    }
    return portable, [unique_plan[key] for key in sorted(unique_plan)], None

def load_authoring_input(path: Path) -> Mapping[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, Mapping):
        raise ValueError("page-author input must be a JSON object")
    return value

def _validated_output(output: Path) -> Path:
    resolved = output.resolve()
    if not (resolved / "state.json").is_file():
        raise CkbError(f"template proposals require an existing CKB output with state.json: {resolved}")
    return resolved

def _expect_object(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise CkbError(f"template proposal {label} must be one JSON object")
    return dict(value)

def _expect_fields(value: Mapping[str, Any], expected: set[str], label: str) -> None:
    actual = set(value)
    unknown = sorted(actual - expected)
    missing = sorted(expected - actual)
    if unknown:
        raise CkbError(f"template proposal {label} contains unknown fields: {unknown}")
    if missing:
        raise CkbError(f"template proposal {label} is missing required fields: {missing}")

def _text(value: Any, label: str, *, maximum: int = 4000) -> str:
    if not isinstance(value, str) or not value.strip():
        raise CkbError(f"template proposal {label} must be non-empty text")
    normalized = value.strip()
    if len(normalized) > maximum or "\x00" in normalized:
        raise CkbError(f"template proposal {label} exceeds its text boundary")
    return normalized

def _string_list(value: Any, label: str, *, allow_empty: bool = False) -> list[str]:
    if not isinstance(value, list) or (not value and not allow_empty):
        suffix = "a list" if allow_empty else "a non-empty list"
        raise CkbError(f"template proposal {label} must be {suffix} of text values")
    result = [_text(item, f"{label}[{index}]", maximum=1000) for index, item in enumerate(value)]
    if len(result) != len(set(result)):
        raise CkbError(f"template proposal {label} contains duplicate values")
    return result

def _boolean(value: Any, label: str) -> bool:
    if not isinstance(value, bool):
        raise CkbError(f"template proposal {label} must be boolean")
    return value

def _integer(value: Any, label: str, *, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not minimum <= value <= maximum:
        raise CkbError(f"template proposal {label} must be an integer between {minimum} and {maximum}")
    return value

def _semantic_version(value: Any, label: str = "version") -> str:
    normalized = _text(value, label, maximum=32)
    if not _SEMVER.fullmatch(normalized):
        raise CkbError(f"template proposal {label} must use MAJOR.MINOR.PATCH")
    return normalized

def _semantic_version_key(value: str) -> tuple[int, int, int]:
    matched = _SEMVER.fullmatch(value)
    if matched is None:
        raise CkbError(f"stored template proposal has an invalid version: {value}")
    return tuple(int(part) for part in matched.groups())  # type: ignore[return-value]

def _template_name(value: Any) -> str:
    normalized = _text(value, "template_name", maximum=80)
    if any(character in normalized for character in ("/", "\\", "\r", "\n", "\t")) or normalized in {".", ".."}:
        raise CkbError("template proposal template_name must be one path-independent name")
    builtin = {name.casefold(): name for name in list_human_page_types()}
    conflict = builtin.get(normalized.casefold())
    if conflict is not None:
        raise CkbError(f"template proposal cannot override or weaken builtin template: {conflict}")
    return normalized

def _target_document() -> dict[str, Any]:
    return {
        "contract_version": HUMAN_PAGE_TEMPLATE_CONTRACT_VERSION,
        "registry_id": HUMAN_PAGE_TEMPLATE_REGISTRY_ID,
        "registry_sha256": human_page_template_registry_sha256(),
        "schema_version": HUMAN_PAGE_TEMPLATE_SCHEMA_VERSION,
    }

def _validate_target(value: Any) -> dict[str, Any]:
    target = _expect_object(value, "target")
    _expect_fields(target, _TARGET_FIELDS, "target")
    expected = _target_document()
    if target != expected:
        raise CkbError(
            "template proposal target drift: expected the current read-only builtin registry "
            f"{expected}, received {target}"
        )
    return expected

def _normalize_count_budget(
    value: Any,
    label: str,
    *,
    allowed_scopes: set[str] | None = None,
) -> dict[str, Any]:
    budget = _expect_object(value, label)
    _expect_fields(budget, _COUNT_BUDGET_FIELDS, label)
    minimum = _integer(budget["minimum"], f"{label}.minimum", minimum=0, maximum=10_000)
    maximum = _integer(budget["maximum"], f"{label}.maximum", minimum=0, maximum=10_000)
    if maximum < minimum:
        raise CkbError(f"template proposal {label}.maximum must be at least minimum")
    scope = _text(budget["scope"], f"{label}.scope", maximum=32)
    allowed_scopes = allowed_scopes or {"entry", "page"}
    if scope not in allowed_scopes:
        raise CkbError(f"template proposal {label}.scope must be one of {sorted(allowed_scopes)}")
    return {
        "counting_rule": _text(budget["counting_rule"], f"{label}.counting_rule"),
        "maximum": maximum,
        "minimum": minimum,
        "overflow_action": _text(budget["overflow_action"], f"{label}.overflow_action"),
        "scope": scope,
    }

def _normalize_fields(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value:
        raise CkbError("template proposal fields must be a non-empty list")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        field = _expect_object(item, f"fields[{index}]")
        _expect_fields(field, _FIELD_FIELDS, f"fields[{index}]")
        field_id = _text(field["field_id"], f"fields[{index}].field_id", maximum=64)
        if not _IDENTIFIER.fullmatch(field_id):
            raise CkbError(f"template proposal fields[{index}].field_id has an invalid identifier")
        value_type = _text(field["value_type"], f"fields[{index}].value_type", maximum=16)
        if value_type not in _VALUE_TYPES:
            raise CkbError(f"template proposal fields[{index}].value_type must be one of {sorted(_VALUE_TYPES)}")
        result.append(
            {
                "field_id": field_id,
                "label": _text(field["label"], f"fields[{index}].label", maximum=120),
                "purpose": _text(field["purpose"], f"fields[{index}].purpose"),
                "required": _boolean(field["required"], f"fields[{index}].required"),
                "value_type": value_type,
            }
        )
    identifiers = [item["field_id"] for item in result]
    if len(identifiers) != len({value.casefold() for value in identifiers}):
        raise CkbError("template proposal fields contain duplicate field_id values")
    if not any(item["required"] for item in result):
        raise CkbError("template proposal must retain at least one required field")
    return result

def _normalize_sections(value: Any, field_ids: set[str]) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value:
        raise CkbError("template proposal sections must be a non-empty list")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        section = _expect_object(item, f"sections[{index}]")
        _expect_fields(section, _SECTION_FIELDS, f"sections[{index}]")
        section_id = _text(section["section_id"], f"sections[{index}].section_id", maximum=64)
        if not _IDENTIFIER.fullmatch(section_id):
            raise CkbError(f"template proposal sections[{index}].section_id has an invalid identifier")
        section_fields = _string_list(section["field_ids"], f"sections[{index}].field_ids")
        unknown = sorted(set(section_fields) - field_ids)
        if unknown:
            raise CkbError(f"template proposal sections[{index}] references unknown fields: {unknown}")
        required = _boolean(section["required"], f"sections[{index}].required")
        disclosure_level = _text(section["disclosure_level"], f"sections[{index}].disclosure_level", maximum=8)
        if disclosure_level not in _DISCLOSURE_LEVELS:
            raise CkbError(f"template proposal sections[{index}].disclosure_level must be L1, L2, or L3")
        empty_behavior = _text(section["empty_behavior"], f"sections[{index}].empty_behavior", maximum=32)
        if empty_behavior not in _EMPTY_BEHAVIORS:
            raise CkbError(f"template proposal sections[{index}].empty_behavior is unsupported")
        if required and empty_behavior == "omit":
            raise CkbError(f"template proposal sections[{index}] required section cannot use empty_behavior=omit")
        if not required and empty_behavior == "error":
            raise CkbError(f"template proposal sections[{index}] optional section cannot use empty_behavior=error")
        result.append(
            {
                "allowed_content": _string_list(section["allowed_content"], f"sections[{index}].allowed_content"),
                "disclosure_level": disclosure_level,
                "empty_behavior": empty_behavior,
                "field_ids": section_fields,
                "forbidden_content": _string_list(section["forbidden_content"], f"sections[{index}].forbidden_content"),
                "freshness_rule": _text(section["freshness_rule"], f"sections[{index}].freshness_rule"),
                "heading": _text(section["heading"], f"sections[{index}].heading", maximum=120),
                "key_entity_budget": _normalize_count_budget(
                    section["key_entity_budget"],
                    f"sections[{index}].key_entity_budget",
                    allowed_scopes={"section"},
                ),
                "length_budget": _normalize_section_length_budget(
                    section["length_budget"], f"sections[{index}].length_budget"
                ),
                "link_budget": _normalize_section_link_budget(
                    section["link_budget"], f"sections[{index}].link_budget"
                ),
                "purpose": _text(section["purpose"], f"sections[{index}].purpose"),
                "required": required,
                "required_content": _string_list(section["required_content"], f"sections[{index}].required_content"),
                "section_id": section_id,
                "source_requirements": _string_list(section["source_requirements"], f"sections[{index}].source_requirements"),
            }
        )
    identifiers = [item["section_id"] for item in result]
    if len(identifiers) != len({value.casefold() for value in identifiers}):
        raise CkbError("template proposal sections contain duplicate section_id values")
    if not any(item["required"] for item in result):
        raise CkbError("template proposal must retain at least one required section")
    referenced = {field_id for item in result for field_id in item["field_ids"]}
    missing = sorted(field_ids - referenced)
    if missing:
        raise CkbError(f"template proposal fields must be owned by at least one section: {missing}")
    return result

def _normalize_examples(value: Any, *, failures: bool) -> list[dict[str, Any]]:
    label = "failure_examples" if failures else "examples"
    expected_fields = _FAILURE_EXAMPLE_FIELDS if failures else _EXAMPLE_FIELDS
    if not isinstance(value, list) or not value:
        raise CkbError(f"template proposal requires at least one {label}")
    result: list[dict[str, Any]] = []
    for index, item in enumerate(value):
        example = _expect_object(item, f"{label}[{index}]")
        _expect_fields(example, expected_fields, f"{label}[{index}]")
        normalized: dict[str, Any] = {
            "content": _text(example["content"], f"{label}[{index}].content", maximum=20_000),
            "name": _text(example["name"], f"{label}[{index}].name", maximum=120),
        }
        if failures:
            normalized["expected_errors"] = _string_list(
                example["expected_errors"], f"{label}[{index}].expected_errors"
            )
        else:
            expected_result = _text(example["expected_result"], f"{label}[{index}].expected_result", maximum=32)
            if expected_result != "passed":
                raise CkbError(f"template proposal {label}[{index}].expected_result must be passed")
            normalized["expected_result"] = expected_result
        result.append(normalized)
    names = [item["name"].casefold() for item in result]
    if len(names) != len(set(names)):
        raise CkbError(f"template proposal {label} contains duplicate names")
    return result
